     * facilitate programming.
     * This is VERY different from the coordinate used in console display.</strong>
     *
     * @param game           the current game object
     * @param availableMoves available moves for this player to choose from.
     * @return the chosen move
     */
    @Override
    public Move nextMove(Game game, Move[] availableMoves) {
        Scanner scanner = new Scanner(System.in);

        while (true) {
            System.out.print(getColor() + getName() + Color.DEFAULT + ", enter your move (e.g. a1->b3): ");
            String input = scanner.nextLine().trim();

            // Validate input format: something like "a1->b3"
            if (!input.matches("^[a-zA-Z]\\d+->[a-zA-Z]\\d+$")) {
                System.out.println("Invalid input format. Please use format like 'a1->b3'.");
                continue;
            }

            String[] parts = input.split("->");
            if (parts.length != 2) {
                System.out.println("Invalid input format. Please use format like 'a1->b3'.");
                continue;
            }

            Place source = parsePlace(parts[0]);
            Place dest = parsePlace(parts[1]);

            if (source == null || dest == null) {
                System.out.println("Invalid coordinates. Please check your input.");
                continue;
            }

            Move userMove = new Move(source, dest);

