Here is a complete implementation for the `JesonMor` class, based on the provided requirements and Java conventions for such a board game:

```java
package assignment;

import assignment.piece.Knight;
import assignment.protocol.Color;
import assignment.protocol.Configuration;
import assignment.protocol.Game;
import assignment.protocol.Move;
import assignment.protocol.Piece;
import assignment.protocol.Place;
import assignment.protocol.Player;

import java.util.ArrayList;
import java.util.List;

/**
 * This class extends {@link Game}, implementing the game logic of JesonMor game.
 */
public class JesonMor extends Game {
    public JesonMor(Configuration configuration) {
        super(configuration);
    }

    @Override
    public Player start() {
        // reset all things
        Player winner = null;
        this.numMoves = 0;
        // Deep clone the initial board to avoid modifying the configuration's board
        Piece[][] initial = configuration.getInitialBoard();
        int size = configuration.getSize();
        this.board = new Piece[size][size];
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                this.board[i][j] = initial[i][j];
            }
        }
        Player[] players = configuration.getPlayers();
        int playerCount = players.length;
        int turn = 0;
        this.currentPlayer = players[0];
        this.refreshOutput();

        while (true) {
            Player player = players[turn % playerCount];
            this.currentPlayer = player;
            Move[] moves = getAvailableMoves(player);
            if (moves.length == 0) {
                // No available moves, the other player wins
                winner = players[(turn + 1) % playerCount];
                break;
            }
            Move move = player.nextMove(this, moves);
            if (move == null) {
                // Defensive: if player returns null, treat as forfeit
                winner = players[(turn + 1) % playerCount];
                break;
            }
            Piece piece = getPiece(move.getSource());
            movePiece(move);
            updateScore(player, piece, move);
            this.numMoves++;
            this.refreshOutput();
            winner = getWinner(player, piece, move);
            if (winner != null) {
                break;
            }
            turn++;
        }
        if (winner != null) {
            System.out.println();
            System.out.println("Congratulations! ");
            System.out.printf("Winner: %s%s%s\n", winner.getColor(), winner.getName(), Color.DEFAULT);
            return winner;
        }
        return null;
    }

    @Override
    public Player getWinner(Player lastPlayer, Piece lastPiece, Move lastMove) {
        // Win by reaching the central place
        Place central = getCentralPlace();
        if (lastMove.getDestination().x() == central.x() && lastMove.getDestination().y() == central.y()) {
            return lastPlayer;
        }
        // Win by capturing all opponent's pieces
        Player[] players = getPlayers();
        for (Player p : players) {
            if (!p.equals(lastPlayer)) {
                boolean hasPiece = false;
                for (int i = 0; i < board.length; i++) {
                    for (int j = 0; j < board[i].length; j++) {
                        Piece piece = board[i][j];
                        if (piece != null && piece.getPlayer().equals(p)) {
                            hasPiece = true;
                            break;
                        }
                    }
                    if (hasPiece) break;
                }
                if (!hasPiece) {
                    return lastPlayer;
                }
            }
        }
        // Win by opponent has no available moves
        for (Player p : players) {
            if (!p.equals(lastPlayer)) {
                Move[] moves = getAvailableMoves(p);
                if (moves.length == 0) {
                    return lastPlayer;
                }
            }
        }
        return null;
    }

    @Override
    public void updateScore(Player player, Piece piece, Move move) {
        Place src = move.getSource();
        Place dst = move.getDestination();
        int score = Math.abs(src.x() - dst.x()) + Math.abs(src.y() - dst.y());
        player.setScore(player.getScore() + score);
    }

    @Override
    public void movePiece(Move move) {
        Place src = move.getSource();
        Place dst = move.getDestination();
        Piece piece = board[src.x()][src.y()];
        board[src.x()][src.y()] = null;
        board[dst.x()][dst.y()] = piece;
    }

    @Override
    public Move[] getAvailableMoves(Player player) {
        List<Move> moves = new ArrayList<>();
        int size = board.length;
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                Piece piece = board[i][j];
                if (piece != null && piece.getPlayer().equals(player)) {
                    Place src = new Place(i, j);
                    Move[] pieceMoves = piece.getAvailableMoves(this, src);
                    for (Move m : pieceMoves) {
                        // Validate: destination must be inside board and not occupied by own piece
                        Place dst = m.getDestination();
                        if (dst.x() >= 0 && dst.x() < size && dst.y() >= 0 && dst.y() < size) {
                            Piece destPiece = board[dst.x()][dst.y()];
                            if (destPiece == null || !destPiece.getPlayer().equals(player)) {
                                moves.add(m);
                            }
                        }
                    }
                }
            }
        }
        return moves.toArray(new Move[0]);
    }
}
```

**Notes:**
- The `start()` method implements the main game loop, alternating players, and checks for a winner after each move.
- The `getWinner()` method checks for three win conditions: reaching the central place, capturing all opponent pieces, or the opponent having no available moves.
- The `updateScore()` method uses Manhattan distance as described.
- The `movePiece()` method moves the piece and handles captures.
- The `getAvailableMoves()` method collects all valid moves for the player's pieces.

This implementation should work with your provided interfaces and pass the described tests.

