Here is a complete implementation of the `JesonMor` class based on your requirements and the provided context.  
This assumes the JesonMor game is a 7x7 chess-like game where each player controls 4 knights, and the goal is to move a knight to the central square (3,3) or eliminate all opponent's knights.

```java
package assignment;

import assignment.piece.Knight;
import assignment.protocol.Color;
import assignment.protocol.Configuration;
import assignment.protocol.Game;
import assignment.protocol.Move;
import assignment.protocol.Piece;
import assignment.protocol.Place;
import assignment.protocol.Player;

import java.util.ArrayList;
import java.util.List;

/**
 * This class extends {@link Game}, implementing the game logic of JesonMor game.
 */
public class JesonMor extends Game {
    public JesonMor(Configuration configuration) {
        super(configuration);
    }

    @Override
    public Player start() {
        // reset all things
        Player winner = null;
        this.numMoves = 0;
        this.board = configuration.getInitialBoard();
        Player[] players = configuration.getPlayers();
        int playerCount = players.length;
        int turn = 0;
        this.currentPlayer = players[0];
        this.refreshOutput();

        while (true) {
            Player player = players[turn % playerCount];
            this.currentPlayer = player;
            Move[] availableMoves = getAvailableMoves(player);

            if (availableMoves.length == 0) {
                // No available moves for this player, other player wins
                winner = players[(turn + 1) % playerCount];
                break;
            }

            Move move = player.nextMove(this, availableMoves);
            if (move == null) {
                // Defensive: if player returns null, skip (shouldn't happen in a correct implementation)
                winner = players[(turn + 1) % playerCount];
                break;
            }

            Piece piece = getPiece(move.getSource());
            movePiece(move);
            updateScore(player, piece, move);
            this.numMoves++;
            this.refreshOutput();

            winner = getWinner(player, piece, move);
            if (winner != null) {
                break;
            }

            turn++;
        }

        if (winner != null) {
            System.out.println();
            System.out.println("Congratulations! ");
            System.out.printf("Winner: %s%s%s\n", winner.getColor(), winner.getName(), Color.DEFAULT);
            return winner;
        }
        return null;
    }

    @Override
    public Player getWinner(Player lastPlayer, Piece lastPiece, Move lastMove) {
        // Win by reaching the central place
        Place central = getCentralPlace();
        if (lastMove.getDestination().x() == central.x() && lastMove.getDestination().y() == central.y()) {
            return lastPlayer;
        }

        // Win by capturing all opponent pieces
        Player[] players = getPlayers();
        for (Player player : players) {
            if (player.equals(lastPlayer)) continue;
            boolean hasPiece = false;
            for (int x = 0; x < board.length; x++) {
                for (int y = 0; y < board[x].length; y++) {
                    Piece p = board[x][y];
                    if (p != null && p.getPlayer().equals(player)) {
                        hasPiece = true;
                        break;
                    }
                }
                if (hasPiece) break;
            }
            if (!hasPiece) {
                return lastPlayer;
            }
        }
        return null;
    }

    @Override
    public void updateScore(Player player, Piece piece, Move move) {
        Place src = move.getSource();
        Place dst = move.getDestination();
        int dist = Math.abs(src.x() - dst.x()) + Math.abs(src.y() - dst.y());
        player.setScore(player.getScore() + dist);
    }

    @Override
    public void movePiece(Move move) {
        Place src = move.getSource();
        Place dst = move.getDestination();
        Piece piece = board[src.x()][src.y()];
        board[src.x()][src.y()] = null;
        board[dst.x()][dst.y()] = piece;
    }

    @Override
    public Move[] getAvailableMoves(Player player) {
        List<Move> moves = new ArrayList<>();
        int size = board.length;
        for (int x = 0; x < size; x++) {
            for (int y = 0; y < size; y++) {
                Piece piece = board[x][y];
                if (piece != null && piece.getPlayer().equals(player)) {
                    Place source = new Place(x, y);
                    Move[] pieceMoves = piece.getAvailableMoves(this, source);
                    for (Move m : pieceMoves) {
                        // Defensive: only add moves that are on board and not capturing own piece
                        Place dst = m.getDestination();
                        if (dst.x() >= 0 && dst.x() < size && dst.y() >= 0 && dst.y() < size) {
                            Piece dstPiece = board[dst.x()][dst.y()];
                            if (dstPiece == null || !dstPiece.getPlayer().equals(player)) {
                                moves.add(m);
                            }
                        }
                    }
                }
            }
        }
        return moves.toArray(new Move[0]);
    }
}
```

**Notes:**
- The `getWinner` method checks for both win conditions: reaching the central square or eliminating all opponent pieces.
- The `updateScore` method uses Manhattan distance as required.
- The `movePiece` method moves the piece and handles captures by overwriting.
- The `getAvailableMoves` method collects all valid moves for all of the player's pieces.
- The `start` method handles the main game loop, alternating turns and checking for a winner after each move.

This should work with your provided framework and pass the sample tests. If you have any specific rules for JesonMor that differ, you may need to adjust the win conditions or move logic accordingly.

