Here is a complete implementation of the `JesonMor` class based on the provided requirements and typical Jeson Mor (Mongolian chess) rules:

```java
package assignment;

import assignment.piece.Knight;
import assignment.protocol.Color;
import assignment.protocol.Configuration;
import assignment.protocol.Game;
import assignment.protocol.Move;
import assignment.protocol.Piece;
import assignment.protocol.Place;
import assignment.protocol.Player;

import java.util.ArrayList;
import java.util.List;

/**
 * This class extends {@link Game}, implementing the game logic of JesonMor game.
 */
public class JesonMor extends Game {
    public JesonMor(Configuration configuration) {
        super(configuration);
    }

    @Override
    public Player start() {
        // reset all things
        Player winner = null;
        this.numMoves = 0;
        // Deep copy the initial board for a fresh start
        Piece[][] initial = configuration.getInitialBoard();
        int size = configuration.getSize();
        this.board = new Piece[size][size];
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                this.board[i][j] = initial[i][j];
            }
        }
        Player[] players = configuration.getPlayers();
        this.currentPlayer = players[0];
        this.refreshOutput();

        int turn = 0;
        while (true) {
            Player player = players[turn % players.length];
            this.currentPlayer = player;

            Move[] availableMoves = getAvailableMoves(player);
            if (availableMoves.length == 0) {
                // No moves, other player wins
                winner = players[(turn + 1) % players.length];
                break;
            }

            Move move = player.nextMove(this, availableMoves);
            if (move == null) {
                // Player gives up, other player wins
                winner = players[(turn + 1) % players.length];
                break;
            }

            Piece piece = getPiece(move.getSource());
            movePiece(move);
            numMoves++;
            updateScore(player, piece, move);
            this.refreshOutput();

            winner = getWinner(player, piece, move);
            if (winner != null) {
                break;
            }

            turn++;
        }

        if (winner != null) {
            System.out.println();
            System.out.println("Congratulations! ");
            System.out.printf("Winner: %s%s%s\n", winner.getColor(), winner.getName(), Color.DEFAULT);
            return winner;
        }
        return null;
    }

    @Override
    public Player getWinner(Player lastPlayer, Piece lastPiece, Move lastMove) {
        // Win by reaching the central place
        Place dest = lastMove.getDestination();
        Place central = getCentralPlace();
        if (dest.x() == central.x() && dest.y() == central.y()) {
            return lastPlayer;
        }

        // Win by capturing all opponent's pieces
        Player[] players = getPlayers();
        for (Player p : players) {
            if (p.equals(lastPlayer)) continue;
            boolean hasPiece = false;
            for (int i = 0; i < board.length; i++) {
                for (int j = 0; j < board[i].length; j++) {
                    Piece piece = board[i][j];
                    if (piece != null && piece.getPlayer().equals(p)) {
                        hasPiece = true;
                        break;
                    }
                }
                if (hasPiece) break;
            }
            if (!hasPiece) {
                return lastPlayer;
            }
        }

        // Win by blocking (other player has no moves)
        Player[] ps = getPlayers();
        for (Player p : ps) {
            if (!p.equals(lastPlayer)) {
                if (getAvailableMoves(p).length == 0) {
                    return lastPlayer;
                }
            }
        }

        return null;
    }

    @Override
    public void updateScore(Player player, Piece piece, Move move) {
        Place src = move.getSource();
        Place dst = move.getDestination();
        int dist = Math.abs(src.x() - dst.x()) + Math.abs(src.y() - dst.y());
        player.setScore(player.getScore() + dist);
    }

    @Override
    public void movePiece(Move move) {
        Place src = move.getSource();
        Place dst = move.getDestination();
        Piece piece = board[src.x()][src.y()];
        board[src.x()][src.y()] = null;
        board[dst.x()][dst.y()] = piece;
    }

    @Override
    public Move[] getAvailableMoves(Player player) {
        List<Move> moves = new ArrayList<>();
        int size = board.length;
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                Piece piece = board[i][j];
                if (piece != null && piece.getPlayer().equals(player)) {
                    Place src = new Place(i, j);
                    Move[] pieceMoves = piece.getAvailableMoves(this, src);
                    for (Move m : pieceMoves) {
                        // Validate move: destination is inside board and not occupied by own piece
                        Place dst = m.getDestination();
                        if (dst.x() >= 0 && dst.x() < size && dst.y() >= 0 && dst.y() < size) {
                            Piece destPiece = board[dst.x()][dst.y()];
                            if (destPiece == null || !destPiece.getPlayer().equals(player)) {
                                moves.add(m);
                            }
                        }
                    }
                }
            }
        }
        return moves.toArray(new Move[0]);
    }
}
```

**Explanation of the implementation:**

- **start()**: Alternates turns between players, gets available moves, asks the player for a move, executes it, updates score, checks for winner, and prints the board.
- **getWinner()**: Checks for three win conditions:
  1. A piece reaches the central place.
  2. All opponent's pieces are captured.
  3. The opponent has no available moves.
- **updateScore()**: Adds the Manhattan distance of the move to the player's score.
- **movePiece()**: Moves the piece on the board.
- **getAvailableMoves()**: For each piece of the player, collects all valid moves.

This implementation assumes that the `Piece#getAvailableMoves(Game, Place)` method for `Knight` and other pieces is implemented correctly and returns only legal moves for that piece type. If you need the `Knight` implementation as well, let me know!

