```java
package assignment.piece;

import assignment.protocol.Game;
import assignment.protocol.Move;
import assignment.protocol.Piece;
import assignment.protocol.Place;
import assignment.protocol.Player;

/**
 * The rule of moving of Archer, which is similar to the moving rule of cannon in Chinese chess.
 * Cannons move like chariots, any distance orthogonally without jumping, but can only capture by jumping a single piece of either colour along the path of attack.
 */
public class ArcherMoveRule implements Rule {
    @Override
    public boolean validate(Game game, Move move) {
        Piece sourcePiece = game.getPiece(move.getSource());
        Piece destPiece = game.getPiece(move.getDestination());

        // Only validate for Archer pieces
        if (!(sourcePiece instanceof Archer)) {
            return true;
        }

        Place src = move.getSource();
        Place dst = move.getDestination();

        int srcX = src.x();
        int srcY = src.y();
        int dstX = dst.x();
        int dstY = dst.y();

        // Must move orthogonally (either same row or same column)
        if (srcX != dstX && srcY != dstY) {
            return false;
        }

        // Count the number of pieces between source and destination
        int countBetween = 0;
        if (srcX == dstX) { // Vertical move
            int minY = Math.min(srcY, dstY);
            int maxY = Math.max(srcY, dstY);
            for (int y = minY + 1; y < maxY; y++) {
                if (game.getPiece(srcX, y) != null) {
                    countBetween++;
                }
            }
        } else { // Horizontal move
            int minX = Math.min(srcX, dstX);
            int maxX = Math.max(srcX, dstX);
            for (int x = minX + 1; x < maxX; x++) {
                if (game.getPiece(x, srcY) != null) {
                    countBetween++;
                }
            }
        }

        if (destPiece == null) {
            // Not a capture: must not jump over any piece
            return countBetween == 0;
        } else {
            // Capture: must jump over exactly one piece
            // And cannot capture own piece
            if (destPiece.getPlayer().equals(sourcePiece.getPlayer())) {
                return false;
            }
            return countBetween == 1;
        }
    }

    @Override
    public String getDescription() {
        return "archer move rule is violated";
    }
}
```

**Explanation:**
- The Archer moves orthogonally (like a rook).
- If not capturing, there must be no pieces between source and destination.
- If capturing, there must be exactly one piece between source and destination, and the destination must be occupied by an opponent's piece.
- If the move is not for an Archer, the rule passes (`true`).

