package assignment.piece;

import assignment.protocol.Game;
import assignment.protocol.Move;
import assignment.protocol.Piece;
import assignment.protocol.Place;

/**
 * The blocking rule applying on Knights. The rule is similar to the blocking rule for horse in Chinese chess.
 * The horse does not jump as the knight does in Western chess, and can be blocked by a piece of either colour located one point horizontally or vertically adjacent to it
 */
public class KnightBlockRule implements Rule {
    @Override
    public boolean validate(Game game, Move move) {
        // Only applies to Knights
        if (!(game.getPiece(move.getSource()) instanceof Knight)) {
            return true;
        }

        Place src = move.getSource();
        Place dst = move.getDestination();
        int dx = dst.x() - src.x();
        int dy = dst.y() - src.y();

        // Knight moves in L-shape: (±2, ±1) or (±1, ±2)
        // For Chinese chess, the "leg" must not be blocked:
        // If dx == 2 or -2, check the square at (src.x() + dx/2, src.y())
        // If dy == 2 or -2, check the square at (src.x(), src.y() + dy/2)

        if (Math.abs(dx) == 2 && Math.abs(dy) == 1) {
            int legX = src.x() + dx / 2;
            int legY = src.y();
            Piece legPiece = game.getPiece(legX, legY);
            if (legPiece != null) {
                return false; // Blocked
            }
        } else if (Math.abs(dx) == 1 && Math.abs(dy) == 2) {
            int legX = src.x();
            int legY = src.y() + dy / 2;
            Piece legPiece = game.getPiece(legX, legY);
            if (legPiece != null) {
                return false; // Blocked
            }
        }
        // If not a valid knight move, let other rules handle it.
        return true;
    }

    @Override
    public String getDescription() {
        return "knight is blocked by another piece";
    }
}
```

**Explanation:**
- The rule checks if the piece being moved is a `Knight`.
- For each possible L-shaped move, it checks the "leg" square (the square adjacent in the direction of the first step).
- If the "leg" square is occupied, the move is invalid (returns `false`).
- Otherwise, the move is allowed (returns `true`).

