package assignment.piece;

import assignment.protocol.Game;
import assignment.protocol.Move;
import assignment.protocol.Piece;
import assignment.protocol.Place;

/**
 * Moving rule of Knight in chess (no block)
 * It moves two squares vertically and one square horizontally, or two squares horizontally and one square vertically
 */
public class KnightMoveRule implements Rule {

    @Override
    public boolean validate(Game game, Move move) {
        Piece piece = game.getPiece(move.getSource());
        if (!(piece instanceof Knight)) {
            // Not a knight, this rule does not apply, so it's valid
            return true;
        }

        Place src = move.getSource();
        Place dest = move.getDestination();

        int dx = Math.abs(dest.x() - src.x());
        int dy = Math.abs(dest.y() - src.y());

        // Knight moves in L-shape: (2,1) or (1,2)
        return (dx == 2 && dy == 1) || (dx == 1 && dy == 2);
    }

    @Override
    public String getDescription() {
        return "knight move rule is violated";
    }
}
```

**Explanation:**
- The rule only applies to moves made by a `Knight`.
- The knight moves in an "L" shape: two squares in one direction and one in the perpendicular direction.
- The method checks if the move matches this pattern and returns `true` if it does, `false` otherwise.

